import json
from io import StringIO

import pandas as pd


def monthly_revenue(json_text: str) -> dict:
    """
    Return a dict mapping 'YYYY-MM' to the float total amount for each calendar month
    from the earliest to the latest month present, including missing months as 0.0.
    """
    records = json.loads(json_text)
    if not records:
        return {}

    df = pd.DataFrame.from_records(records)
    if df.empty:
        return {}

    df = df.copy()
    df["date"] = pd.to_datetime(df["date"])
    df["amount"] = df["amount"].astype(float)

    monthly = df.set_index("date")["amount"].sort_index().resample("ME").sum()

    out = {}
    for ts, total in monthly.items():
        out[ts.strftime("%Y-%m")] = float(total)
    return out
